    "platform fee, paid automatically as network value (no separate approval step). Any amount you send above that is refunded.": "作为平台费，以网络原生币值自动支付（无需单独授权）。多付的部分将退还。", "Launch coin": "发射代币", "Launching…": "发射中…",
