    "No wallet found in this browser — paste your address instead, or open this page in your wallet app's browser.": "此浏览器中没有找到钱包——请粘贴地址，或在钱包 App 的浏览器中打开本页。",
    "The wallet request was declined.": "钱包请求被拒绝。",
    "Your wallet didn't answer — try again.": "钱包没有响应——请重试。",
    "Anyone who opens ARCIRCLE PAD through this link is remembered as your invite in their browser for 30 days, and CirclePad contributions made through it are credited to you. Referral share is a candidate mechanic — nothing is paid for invites yet.": "通过此链接打开 ARCIRCLE PAD 的人会在其浏览器中被记为你的邀请 30 天，通过它进行的 CirclePad 参与也会记在你名下。推荐分成是候选机制——目前邀请还没有任何报酬。",
    "Support": "支持",
