    "We are here": "我们在这里",
    "Hear it first": "第一时间获知",
    "Be there when the rules are published.": "规则发布时，第一时间在场。",
    "Reward rules, the revenue split and every buyback are announced on these two channels first.": "奖励规则、收入分配和每一次回购都会首先在这两个频道公布。",
    "Launch alerts on Telegram": "Telegram 发射提醒",
    "Follow on X": "在 X 上关注",
    "Questions about rewards.": "关于奖励的问题。",
    "Are rewards live?": "奖励上线了吗？",
    "Not yet. The program is in design, and it only goes live once its rules are published on this page.": "还没有。计划仍在设计中，只有在规则发布于本页后才会上线。",
    "Do I need to do anything now?": "我现在需要做什么吗？",
    "No. There is nothing to register or claim today. The wallet check above only shows the on-chain activity the programs are designed around.": "不需要。目前没有需要注册或领取的内容。上方的钱包查询只显示计划所围绕的链上活动。",
    "Will buying just before a snapshot help?": "在快照前买入有用吗？",
    "The candidate design uses time-weighted balances and unannounced snapshots, so a balance held for a moment counts for very little.": "候选设计使用时间加权余额和不预告的快照，所以短暂持有的余额几乎不算数。",
    "Where does the money come from?": "资金从哪里来？",
    "From what the ecosystem earns: the five revenue sources above. No new $ARCIRCLE is ever minted to pay rewards.": "来自生态的收入：上方的五个收入来源。绝不会为支付奖励而铸造新的 $ARCIRCLE。",
    "Does my vote in the poll decide the design?": "我的投票会决定设计吗？",
    "It is a signal, not a binding vote. It shows which mechanics the community cares about while the rules are being written.": "这是一种信号，而不是有约束力的投票。它在规则制定期间显示社区关心哪些机制。",
    "Is holding $ARCIRCLE a claim on revenue?": "持有 $ARCIRCLE 是对收入的索取权吗？",
    "No. $ARCIRCLE is a community memecoin — holding it is not a share, a claim on revenue or a right to any payment.": "不是。$ARCIRCLE 是社区 meme 币——持有它不代表股份、收入索取权或任何获得付款的权利。",
