    "There isn't one yet — $ARCIRCLE is relaunching. The new contract address will be posted on this page and by": "还没有——$ARCIRCLE 正在重新发行。新合约地址将在上线时公布在本页以及",
    "when it goes live. Don't trust addresses from anywhere else.": "上线时公布。不要相信其他来源的地址。",
    "Not yet. Join the launch alerts on Telegram (": "还不能买。加入 Telegram 上线提醒（",
    ") to hear the moment it goes live.": "），上线第一时间通知你。",
    "Not live yet — $ARCIRCLE is relaunching": "尚未上线——$ARCIRCLE 正在重新发行",
    "Starts when $ARCIRCLE is live": "$ARCIRCLE 上线后开始",
    "$ARCIRCLE is relaunching — nothing to hold yet": "$ARCIRCLE 正在重新发行——暂时无法持有",
    "Starts counting when $ARCIRCLE is live": "$ARCIRCLE 上线后开始计算",
    "Every launch gets a real Uniswap v4 pool in the same transaction — paired with USDC, Arc's own native currency, or with any Arc token you choose.": "每次发射都会在同一笔交易中获得真正的 Uniswap v4 池——与 Arc 原生货币 USDC 或你选择的任意 Arc 代币配对。",
