    "Full chart ↗": "完整图表 ↗",
    "In the pool": "池中",
    "Is the liquidity locked?": "流动性锁定了吗？",
    "Launch & trade": "发射与交易",
    "Launch fees + $ARCIRCLE creator fee, in USDC": "发射费 + $ARCIRCLE 创作者费用，以 USDC 计",
    "Launch fees, ArcPad's platform allocation and trading fees, CirclePad's raise share, and $ARCIRCLE's own creator fee flow in.": "发射费、ArcPad 的平台分配与交易手续费、CirclePad 的募资分成，以及 $ARCIRCLE 自身的创作者费用都会流入。",
    "Launch fees, trading fees, raise shares and $ARCIRCLE's own creator fee all flow into the same flywheel.": "发射费、交易手续费、募资分成和 $ARCIRCLE 自身的创作者费用全部流入同一个飞轮。",
    "Launchpad": "发射平台",
    "Liquidity lock": "流动性锁定",
    "Loading chart…": "正在加载图表…",
