    "Pool ID": "池 ID",
    "Recent trades": "最近交易",
    "Since": "开始于",
    "The market, read straight from the pool.": "直接从池中读取的市场数据。",
    "Trade $ARCIRCLE": "交易 $ARCIRCLE",
    "Uniswap v4 · paired with USDC": "Uniswap v4 · 与 USDC 配对",
    "What is the creator fee?": "什么是创作者费用？",
    "Where it trades": "交易地点",
    "Indexing the pool's history…": "正在索引池的历史…",
    "No trades yet.": "暂无交易。",
    "No buybacks yet — each one will appear here with its transaction.": "暂无回购——每次回购都会连同交易显示在这里。",
    "Live $ARCIRCLE data unavailable right now": "暂时无法获取 $ARCIRCLE 实时数据",
    "$ARCIRCLE on argus.world ↗": "argus.world 上的 $ARCIRCLE ↗",
    "$ARCIRCLE trades in a Uniswap v4 pool on Arc, launched through Argus with its liquidity locked. Every number here comes from the chain — refreshed every 30 seconds.": "$ARCIRCLE 通过 Argus 发射，在 Arc 上的 Uniswap v4 池中交易，流动性已锁定。这里的每个数字都来自链上，每 30 秒刷新一次。",
    "$ARCIRCLE trades on Argus, in a Uniswap v4 pool on Arc. Arc uses USDC for gas, so USDC is all you need.": "$ARCIRCLE 在 Argus 上交易，使用 Arc 上的 Uniswap v4 池。Arc 用 USDC 支付 Gas，所以你只需要 USDC。",
    "$ARCIRCLE trades on Argus, in a Uniswap v4 pool paired with USDC. Trades settle there, in your own wallet — ArcPad never holds your funds.": "$ARCIRCLE 在 Argus 上交易，使用与 USDC 配对的 Uniswap v4 池。交易在那里通过你自己的钱包结算——ArcPad 从不持有你的资金。",
    "90% of tax": "税费的 90%",
    "90% of the buy / sell tax on every $ARCIRCLE trade": "每笔 $ARCIRCLE 交易买入 / 卖出税的 90%",
    "90% of the tax on every $ARCIRCLE trade": "每笔 $ARCIRCLE 交易税费的 90%",
    "Argus locker · no withdraw function": "Argus 锁仓合约 · 无提取功能",
    "Argus · Uniswap v4": "Argus · Uniswap v4",
    "Bonding milestone": "绑定里程碑",
    "Buy on Argus ↗": "在 Argus 购买 ↗",
    "Every $ARCIRCLE trade pays the launch's buy or sell tax — set once at launch between 1% and 10%, and fixed forever — on top of the 1% pool fee. Argus keeps 10% of the tax; the other 90% goes to the creator's allocation, in USDC. That share is one of the five revenue sources that feed the flywheel.": "每笔 $ARCIRCLE 交易在 1% 池费之外，还需支付发射时一次性设定（1%–10%）并永久固定的买入或卖出税。Argus 保留税费的 10%，其余 90% 以 USDC 进入创作者分配。这部分是推动飞轮的五个收入来源之一。",
    "Locked by Argus": "由 Argus 锁定",
    "No virtual curve and no migration: the whole supply has sat in one locked Uniswap v4 position since the first block. Every trade pays the 1% pool fee plus the launch's fixed buy / sell tax; Argus keeps 10% of the tax and 90% goes to the creator's allocation — one of the revenue sources below.": "没有虚拟曲线，也不会迁移：全部供应量从第一个区块起就在一个锁定的 Uniswap v4 仓位中。每笔交易支付 1% 池费和发射时固定的买入 / 卖出税；Argus 保留税费的 10%，90% 进入创作者分配——这是下方的收入来源之一。",
    "No. Argus put all 1,000,000,000 $ARCIRCLE into the pool's liquidity position at launch; there is no separate team allocation. The supply split above shows where it sits today.": "没有。Argus 在发射时把全部 1,000,000,000 枚 $ARCIRCLE 放入池子的流动性仓位，没有单独的团队分配。上方的供应分布显示了它们目前的位置。",
    "On Argus, where it launched. It trades in a Uniswap v4 pool on Arc, so it also shows up on Dexscreener and other trackers that index Arc — always check the contract address first.": "在其发射平台 Argus 上。它在 Arc 上的 Uniswap v4 池中交易，所以也会出现在 Dexscreener 等收录 Arc 的追踪工具中——请务必先核对合约地址。",
    "Open $ARCIRCLE on Argus": "在 Argus 上打开 $ARCIRCLE",
    "Trading tax": "交易税",
    "Yes. Argus puts the whole supply into a single Uniswap v4 position when the pool is created and hands it to a locker contract that has no withdraw function — nobody, Argus included, can pull that liquidity.": "是的。Argus 在创建池子时把全部供应量放入一个 Uniswap v4 仓位，并交给一个没有提取功能的锁仓合约——包括 Argus 在内，任何人都无法撤出这部分流动性。",
    "Trading on Argus · liquidity locked": "在 Argus 交易 · 流动性已锁定",
    "Trading on Argus · Uniswap v4 pool": "在 Argus 交易 · Uniswap v4 池",
    "Fixed at launch (1–10%)": "发射时固定（1–10%）",
    "Reached": "已达成",
    "$ARCIRCLE launched on Argus with its whole supply in one locked Uniswap v4 position, and 12.63% of the supply has been burned. ArcPad live on Arc mainnet. CirclePad escrow deployed.": "$ARCIRCLE 在 Argus 上发射，全部供应量放在一个锁定的 Uniswap v4 仓位中，目前已销毁 12.63% 的供应量。ArcPad 已在 Arc 主网上线，CirclePad 托管合约已部署。",
    ", which no one controls — those tokens can never move again. Circulating supply:": "，该地址无人控制——这些代币永远无法再转移。流通量：",
    ", which no one controls. Those tokens can never move again; the live total is shown above.": "，该地址无人控制。这些代币永远无法再转移；实时总量显示在上方。",
    "12.63% of it already burned ↗": "其中 12.63% 已销毁 ↗",
    "Burn": "销毁",
    "Burned": "已销毁",
    "Burned forever": "永久销毁",
    "Buybacks & burns": "回购与销毁",
    "Buybacks, burns and who holds $ARCIRCLE.": "回购、销毁，以及谁持有 $ARCIRCLE。",
    "Every $ARCIRCLE buy by the platform's wallets and every burn shows up here with its transaction, and the supply split is rebuilt from every transfer since launch.": "平台钱包每一次买入 $ARCIRCLE 和每一次销毁都会连同交易显示在这里，供应分布根据发射以来的每笔转账重新计算。",
    "Has any $ARCIRCLE been burned?": "$ARCIRCLE 有被销毁过吗？",
    "See the transaction ↗": "查看交易 ↗",
    "Yes, twice so far: 116,772,290.56 $ARCIRCLE on 25 September 2026 and 9,491,742.10 on 26 September 2026 — 126,264,032.66 in total, 12.63% of the supply — sent to the dead address": "是的，目前共两次：2026 年 9 月 25 日 116,772,290.56 枚、2026 年 9 月 26 日 9,491,742.10 枚——合计 126,264,032.66 枚 $ARCIRCLE（供应量的 12.63%）被发送到销毁地址",
    "of supply ↗": "的供应量 ↗",
    "of the 1,000,000,000 supply was sent to the dead address": "的 1,000,000,000 总供应量被发送到销毁地址",
    "of the supply burned forever": "的供应量已永久销毁",
