    "Utility · Circle CCTP": "工具 · Circle CCTP",
    "Move USDC between Arc and other chains. It's Circle's own Cross-Chain Transfer Protocol: native USDC is burned on one side and minted on the other — no wrapped tokens, no pools, and Circle delivers it on the other side so you don't need gas there.": "在 Arc 与其他链之间转移 USDC。使用 Circle 官方的跨链转账协议（CCTP）：在一侧销毁原生 USDC，在另一侧铸造——没有包装代币，没有资金池，并由 Circle 在目标链代为送达，因此你在那边不需要 Gas。",
