    "of the raise": "占募集总额",
    "wallets in": "参与钱包",
    "Can I get my USDC back?": "我可以取回 USDC 吗？",
    "Yes — any amount, any time until the 72 hours are up. \"Withdraw my contribution\" sends it straight back from the escrow; nobody else can move your USDC while the raise is open.": "可以 —— 72 小时结束前，任意金额随时可取回。点击“取回我的参与金”即可从托管直接退回；募集进行期间，任何人都无法动用你的 USDC。",
    "What happens when the 72 hours end?": "72 小时结束后会发生什么？",
    "Contributions and withdrawals stop. Everything the escrow holds is then split in one transaction: 80% to the recipient wallet, 15% to the treasury wallet and 5% to the platform wallet — the addresses above, fixed in the contract.": "参与和取回都会停止。随后托管中的全部资金通过一笔交易分配：80% 给接收钱包，15% 给金库钱包，5% 给平台钱包 —— 即上方显示、写死在合约中的地址。",
    "Who can split it, and can it happen early?": "谁可以执行分配？能否提前？",
    "Only the recipient wallet can call the split, and the contract refuses it until the raise has closed.": "只有接收钱包可以执行分配，且在募集结束前合约会拒绝执行。",
    "How is the new coin shared with contributors?": "新代币如何分配给参与者？",
    "Not decided yet — it will be announced here before the raise opens. The list of contributors at the close is public on-chain, so anyone can check who was in and how much.": "尚未确定 —— 将在募集开始前于此公布。结束时的参与者名单在链上公开，任何人都能查看谁参与了、投入多少。",
    "Is the contract's code public?": "合约代码公开吗？",
    "Yes — the escrow's source is verified on the explorer, so what it does can be read line by line.": "是的 —— 托管合约源码已在浏览器上验证，可以逐行查看其逻辑。",
    "The source hasn't been verified on the explorer yet. The code is in the project's repository (contracts/BigPadEscrow.sol); this note changes once it is verified.": "源码尚未在浏览器上验证。代码位于项目仓库（contracts/BigPadEscrow.sol）；验证后此说明会更新。",
    "Opens in": "距开始",
    "Opening any moment": "即将开始",
    "No contributors yet — be the first dot.": "还没有参与者 —— 成为第一个点吧。",
    "Every contributor becomes a dot here once the raise opens.": "募集开始后，每位参与者都会在这里成为一个点。",
