    "Candidates go up during the raise. Voting opens the moment it closes and runs for 48 hours.": "募集期间公布候选项。募集结束的那一刻投票开启，持续 48 小时。",
    "Voting is open. Every contributor has a say, weighted by the USDC they put in.": "投票已开启。每位参与者都有发言权，权重为其投入的 USDC。",
    "Voting has closed — these results are final.": "投票已结束 —— 结果为最终结果。",
    "Candidates are up — voting opens at the close.": "候选项已公布 —— 募集结束时开启投票。",
    "Voting is open — cast yours.": "投票已开启 —— 快来投票。",
    "Voting has closed — see the result.": "投票已结束 —— 查看结果。",
    "Voting opens at the close — the vote contract is being set up.": "募集结束时开启投票 —— 投票合约正在准备中。",
    "The vote contract for this round is being set up. Candidates will appear here, and voting opens the moment the raise closes.": "本轮投票合约正在准备中。候选项将显示在这里，募集结束的那一刻投票开启。",
    "Voting opens the moment the raise closes and runs for 48 hours. Your weight is the USDC you put in, locked in at the close.": "募集结束的那一刻投票开启，持续 48 小时。你的权重是你投入的 USDC，在募集结束时锁定。",
