    "This pool runs a hook contract ARCIRCLE PAD doesn't recognise. A hook can change swaps, fees or withdrawals — only add liquidity if you trust it.": "这个池子使用 ARCIRCLE PAD 无法识别的 hook 合约。hook 可以改变兑换、手续费或提取——只有在信任它时才添加流动性。",
