    "vs": "对比",
    "Arbitrage bots will trade it back to the market price, at your deposit's expense.": "套利机器人会把价格拉回市场价,损失由你的存入资金承担。",
    "The Token Scanner found": "代币扫描器发现",
    "A taxed token loses part of every deposit and withdrawal to the tax, and pool math can break.": "带税代币每次存入和提取都会被扣税,池子计算也可能出错。",
