    "Pool created — your position is below.": "池子已创建——你的仓位在下方。",
    "A new Uniswap v4 pool on Arc, with no hook. You set its first price and make the first deposit.": "在 Arc 上创建一个没有 hook 的 Uniswap v4 新池子。由你设定初始价格并完成首次存入。",
