    "ArcPad pool · 1 USDC fee · your own add-on fee": "ArcPad 池 · 1 USDC 手续费 · 你自己的附加费",
    "Argus Portal #8 · buy / sell tax · 70% of creator fees to you": "Argus Portal #8 · 买/卖税 · 创作者手续费的 70% 归你",
    "Launched on Argus, from your own wallet": "从你自己的钱包在 Argus 发射",
    "Your coin goes live on Argus Portal #8 with a Uniswap v4 pool and fixed buy / sell taxes, paid in USDC. Argus takes its own share of every fee as usual. Of the creator share, 70% is yours and 30% goes to the ARCIRCLE PAD treasury — set on-chain with Argus's own fee split.": "你的代币会在 Argus Portal #8 上线，带有 Uniswap v4 池和固定的买/卖税（以 USDC 支付）。Argus 照常从每笔手续费中收取自己的份额。创作者份额中 70% 归你，30% 进入 ARCIRCLE PAD 金库 — 通过 Argus 自己的手续费分配功能在链上设置。",
    "taken on every trade, fixed forever": "每笔交易收取，永久固定",
    "Buy tax": "买入税",
    "Sell tax": "卖出税",
    "Each side 0–10%, and not both 0. Argus fixes them at launch — nobody can change them later.": "每边 0–10%，不能都为 0。Argus 在发射时固定，之后任何人都无法更改。",
    "your four shares, after Argus's cut": "扣除 Argus 份额后的四项分配",
    "Opening buy": "开盘买入",
    "Argus requires one — your first tokens, bought in the launch transaction": "Argus 必需 — 在发射交易中买入的第一批代币",
    "Minimum buy": "最低买入",
    "Reading Argus's minimum…": "正在读取 Argus 的最低金额…",
    "ArcPad support for coins launched here": "对在这里发射的代币的 ArcPad 支持",
    "At a $20K market cap we help update the coin's Dexscreener info — logo, links and description.": "市值达到 $20K 时，我们协助更新代币的 Dexscreener 信息 — 标志、链接和介绍。",
    "At a $100K market cap we add marketing support, decided case by case — boosts, calls and promotion.": "市值达到 $100K 时，我们视情况提供营销支持 — 推广位、喊单和宣传。",
    "Support may be refused if our Token Scanner finds signs of manipulation — snipers, bundled buys, wash trading or similar — or if the 70 / 30 fee split is removed.": "如果我们的 Token Scanner 发现操纵迹象（狙击、捆绑买入、刷量等），或 70 / 30 手续费分配被移除，可能不予支持。",
    "This is ARCIRCLE PAD's own support policy, not a contract, and it can change. The coin's fees and taxes are Argus's and follow Argus's rules.": "这是 ARCIRCLE PAD 自己的支持政策，不是合约，可能会变更。代币的手续费和税属于 Argus，遵循 Argus 的规则。",
    "I understand: two signatures (the launch, then the 70 / 30 fee split), taxes fixed forever, and support as described above.": "我明白：两次签名（发射，然后 70 / 30 手续费分配），税率永久固定，支持如上所述。",
    "70% of fees to you": "70% 手续费归你",
    "Your coin goes live on Argus the moment the launch confirms; the fee split is the second signature.": "发射确认后代币立即在 Argus 上线；手续费分配是第二次签名。",
