    "Argus's share is read live from the Portal. Creator fees wait on Argus until claimed — you and ARCIRCLE PAD each claim your own part at argus.world/claim.": "Argus 的份额实时从 Portal 读取。创作者手续费在领取前留在 Argus — 你和 ARCIRCLE PAD 各自在 argus.world/claim 领取自己的部分。",
    "Argus's minimum is {n} USDC. More buys you more of your coin at the opening price; Argus refuses an opening buy that would reach its bonding mark.": "Argus 的最低金额是 {n} USDC。买得越多，以开盘价获得的代币越多；会触及绑定线的开盘买入会被 Argus 拒绝。",
