    "A mine runs 3–60 days in six equal layers. The first layer releases half of everything, so the earliest builders dig the richest ground.": "一座矿运行 3–60 天，分为六个等长的层。第一层释放一半的总量，所以最早的建造者挖到最富的矿。",
    "A pickaxe is yours for good and works in every mine. An upgrade costs only the difference. Every $ARCIRCLE you pay is burned.": "镐子永久归你，在所有矿场都能用。升级只需支付差价。你支付的 $ARCIRCLE 全部销毁。",
