    "Next share": "下一份",
    "No crews yet — found the first one on the Your builder tab.": "还没有战队——在我的建造者页创建第一个。",
    "No points yet this month.": "本月还没有积分。",
    "Nobody has found one yet.": "还没有人挖到。",
    "Nothing to claim in any mine yet.": "还没有可领取的矿场。",
    "On battery and below 30% — mining on one core.": "电池低于 30%——只用一个核心挖矿。",
    "One X account per wallet, an hourly cap per wallet.": "每个钱包一个 X 账号，每个钱包每小时有上限。",
    "One line about it": "一句话介绍",
    "Only the best ore in a share counts. The Lucky gem makes every ore twice as likely.": "每份只计最好的一种矿石。幸运宝石让每种矿石的概率翻倍。",
    "Opening a mine and joining one each cost 1 USDC worth of $ARCIRCLE — burned, never paid to anyone.": "开矿和加入各需 1 USDC 等值的 $ARCIRCLE——全部销毁，不付给任何人。",
    "Opening costs": "开矿费用",
    "Overtime barrel": "加班酒桶",
    "Payout in": "距发放",
    "Pick a mine, press Start, and your builder digs with your browser. Every hour the mine pays out by the work done. Rare ores, pickaxes, pets and ranks make it a game.": "选一座矿，点击开始，你的建造者就用浏览器挖矿。每小时按工作量发放。稀有矿石、镐子、宠物和等级让它变成一场游戏。",
    "Pickaxes ×1.15 to ×2.7. Bonuses add up to +100% at most:": "镐子 ×1.15 至 ×2.7。加成合计最多 +100%：",
    "Points in every mine this month.": "本月所有矿场的积分。",
    "Press Start": "点击开始",
    "Press Start. Your builder swings for real — your browser does the hashing, only while this tab is open.": "点击开始。你的建造者真的在挖——只有在此标签页打开时浏览器才计算哈希。",
    "Rank +2% to +10%; Lantern +15%, Dynamite +50%": "等级 +2% 至 +10%；矿灯 +15%，炸药 +50%",
