    "Very high volume for its liquidity": "相对流动性成交量极高",
    "Wallet approvals": "钱包授权",
    "Wallets that look like one owner, and what they hold together.": "看起来属于同一人的钱包，以及它们合计持有多少。",
    "Wallets that passed tokens between each other, got them from the same sender, or bought in the same first block are probably one owner — together they hold more than any one of them shows.": "彼此转过代币、从同一发送者收到、或在同一首个区块买入的钱包，多半属于同一人——合起来持有的比单个看起来多。",
    "Webhook added": "已添加 Webhook",
    "What a buy would get you, how far it moves the price, and what selling straight back would return.": "买入能得到多少、价格会动多少、立即卖回能拿回多少。",
    "What changed": "有什么变化",
    "What else the wallet that created this token has made. A creator whose other tokens scored high risk is a warning sign.": "创建这个代币的钱包还做过什么。其他代币评分高风险的创建者是个危险信号。",
    "What the price would do if the biggest holders sold everything.": "如果最大的持有人全部卖出，价格会怎样。",
    "When many different wallets buy in the exact same first block, it is usually one person splitting a buy to look like many holders.": "许多不同钱包在同一个首个区块买入，通常是一个人拆分买单，装成很多持有人。",
    "Where the points went": "扣分分布",
    "Where this answer comes from": "这个答案的来源",
    "While we test, every wallet gets the free daily unlocks. Later, free unlocks are planned for wallets holding 100,000 $ARCIRCLE.": "测试期间每个钱包都有每日免费解锁。之后计划只给持有 100,000 $ARCIRCLE 的钱包免费解锁。",
    "Who does the trading. When a handful of wallets make most of the trades, volume can be faked to look popular.": "谁在交易。少数钱包包揽大部分交易时，成交量可能是刷出来显得热门的。",
    "Who trades": "谁在交易",
    "You can buy and sell it, with no tax in the dry run.": "可以买卖，模拟中没有税。",
    "You can buy and sell it; about {x} is taken per trade.": "可以买卖；每笔交易约扣 {x}。",
