    "Written by ARCIA from this scan. Not financial advice.": "由 ARCIA 根据这次扫描撰写。不构成投资建议。",
    "ARCIA's model isn't answering right now, so this is the scanner's own summary.": "ARCIA 的模型现在没有响应，这是扫描器自己的总结。",
    "ArcPad": "ArcPad",
    "Uniswap v4 + hook": "Uniswap v4 + 钩子",
