    "Live log": "实时记录",
    "Live — real trades": "实盘——真实交易",
    "Model trained on": "模型已学习",
    "Money limits": "资金限制",
    "Never $ARCIRCLE itself": "绝不交易 $ARCIRCLE 本身",
    "No Argus launches in the last three days yet.": "最近三天还没有 Argus 发行。",
    "No Token Scanner critical flag": "没有代币扫描器严重标记",
    "No burn yet — it starts with the first profitable day.": "还没有销毁——从第一个盈利日开始。",
    "No message, chat or command can make it trade": "任何消息、聊天或指令都不能让它交易",
    "No open positions. ARCIA is watching new launches for a setup that passes every gate.": "没有持仓。ARCIA 正在盯着新发行，寻找通过所有关卡的机会。",
    "No paper trades closed yet.": "还没有平仓的模拟交易。",
    "No real positions in paper mode.": "模拟模式下没有真实持仓。",
    "No real trades closed yet. The first 25 are the warm-up: small trades on every setup that passes the gates, to learn fast.": "还没有平仓的真实交易。前 25 笔是热身：通过关卡的每个机会都小额交易，以便快速学习。",
    "Not ArcPad's own Argus launches — the platform earns their fees": "不交易 ArcPad 自己的 Argus 发行——平台从中赚取费用",
    "Nothing yet — it learns from the first closed trades.": "还没有——从第一批平仓交易开始学习。",
    "Nothing yet. Every buy, sell and burn will appear here with its transaction.": "还没有。每笔买入、卖出和销毁都会连同交易哈希显示在这里。",
    "Once a day,": "每天一次，",
    "Only new coins launched on Argus, paired with USDC": "只交易在 Argus 发行、与 USDC 配对的新币",
    "Open in Token Scanner": "在代币扫描器中打开",
    "Open positions": "当前持仓",
    "Paper": "模拟",
    "Paper trades running": "进行中的模拟交易",
    "Paper — practising, no money moves": "模拟——练习中，不动用资金",
    "Passed on": "放弃的币",
    "Profit / loss": "盈亏",
    "Profit over time": "盈亏走势",
    "Real": "真实",
    "Right: more of it has meant a winning trade. Left: a losing one.": "右侧：数值越高越常盈利。左侧：越常亏损。",
