    "Two wallet confirmations: first a fresh escrow contract is deployed (same recipient, platform and treasury wallets as Round #1), then its 72-hour raise opens right away. This can't be undone.": "需两次钱包确认：先部署新的托管合约（接收、平台、金库钱包与第 1 轮相同），随后立即开启 72 小时募资。无法撤销。",
