    "A 72-hour USDC raise in an on-chain escrow: 1,565.66 USDC from 21 wallets. Closed 29 Sep 2026 and split 80 / 15 / 5 in one transaction.": "链上托管 72 小时 USDC 募集:21 个钱包共 1,565.66 USDC。2026 年 9 月 29 日结束,一笔交易完成 80 / 15 / 5 分配。",
    "250 votes burned 250,000 $ARCIRCLE and chose the coin's name, ticker, logo and roadmap: ARCIA, $ARCIA.": "250 票销毁了 250,000 $ARCIRCLE,选出了币的名称、代码、Logo 和路线图:ARCIA、$ARCIA。",
