    "Argus launch share": "Argus 发币分成",
    "30% of the creator share on coins launched on Argus through ArcPad": "通过 ArcPad 在 Argus 发行的币的创作者份额的 30%",
    "Paid tools and ARCIA 402; Token Scanner unlocks and Builder Mine burn $ARCIRCLE directly": "付费工具与 ARCIA 402;代币扫描器解锁和 Builder Mine 直接销毁 $ARCIRCLE",
    "$ARCIRCLE's supply is fixed at one billion. Rewards and the burn engine run on real ecosystem income: the sources that turn the $ARCIRCLE flywheel.": "$ARCIRCLE 供应量固定为十亿。奖励与销毁引擎依靠真实的生态收入运转:也就是推动 $ARCIRCLE 飞轮的收入来源。",
    "5% of each round's raise at the close": "每轮结束时募集额的 5%",
    "See the on-chain activity the programs are designed around, and how much $ARCIRCLE a wallet has burned — read live from Arc. This is a preview, not an eligibility check: no rewards are live yet and nothing here promises any.": "查看奖励计划所依据的链上活动,以及钱包销毁了多少 $ARCIRCLE — 实时读取自 Arc。这只是预览,不是资格检查:奖励尚未上线,这里也不承诺任何奖励。",
    "First CirclePad round: Round #1 raised 1,565.66 USDC and launched $ARCIA": "第一轮 CirclePad:第 1 轮募集 1,565.66 USDC 并发行 $ARCIA",
    "Burns in every utility, tracked live by source on this page": "每个工具的销毁,在本页面按来源实时追踪",
    "Treasury buybacks of $ARCIRCLE, posted with transaction links": "$ARCIRCLE 金库回购,附交易链接公布",
    "Publish the flywheel revenue split": "公布飞轮收入分配",
    "Phase 2 — Burn engine & rewards": "第二阶段 — 销毁引擎与奖励",
    "The burn engine: the ARCIRCLE reward contract with $ARCIRCLE and $ARCIA, automatic buyback-and-burn from utility and platform revenue (timeline shared as each piece is ready)": "销毁引擎:包含 $ARCIRCLE 与 $ARCIA 的 ARCIRCLE 奖励合约,用工具与平台收入自动回购销毁(时间表将在每部分准备好时公布)",
    "What is the burn engine?": "什么是销毁引擎?",
    "A reward contract that receives utility and platform revenue and buys back and burns $ARCIRCLE and $ARCIA automatically, so no one has to press a button. The core framework is being built; contract details, burn ratios and the rollout timeline are shared as each piece is ready.": "一个接收工具与平台收入、自动回购并销毁 $ARCIRCLE 和 $ARCIA 的奖励合约,无需任何人按按钮。核心框架正在建设中;合约细节、销毁比例和上线时间表将在每部分准备好时公布。",
    "How are burns labeled by source?": "销毁来源是如何标注的?",
    "Each transfer to 0x…dEaD is matched to its transaction: the contract it called (burn-to-vote, Builder Mine, ARCIA DESK), or the Token Scanner unlock or secret file it paid for. Anything else is shown as a direct burn from a wallet.": "每笔发送到 0x…dEaD 的转账都会与其交易匹配:它调用的合约(销毁投票、Builder Mine、ARCIA DESK),或它支付的代币扫描器解锁或秘密档案。其他情况显示为钱包直接销毁。",
    "Not yet. Burns are live today in every utility; the reward contract and the holder and creator programs are being built, and they only go live once their rules are published on this page.": "还没有。今天每个工具都在销毁;奖励合约以及持有者和创作者计划正在建设中,只有在规则公布在本页面后才会上线。",
    "From utilities and the community": "来自工具与社区",
    "From the team": "来自团队",
    "Each group's bars are scaled to its largest source; the % is the share of everything burned.": "每组的条形按组内最大来源缩放;百分比是占全部销毁量的比例。",
