    "What it does": "用途",
    "Every utility already burns $ARCIRCLE. Next, a reward contract with $ARCIRCLE and $ARCIA turns utility and platform revenue into automatic buyback-and-burn.": "每个工具都已在销毁 $ARCIRCLE。下一步,包含 $ARCIRCLE 与 $ARCIA 的奖励合约会把工具与平台收入变成自动回购销毁。",
    "See the burn engine →": "查看销毁引擎 →",
    "What $ARCIRCLE does": "$ARCIRCLE 的用途",
    "Hold it, use it, burn it.": "持有它,使用它,销毁它。",
    "$ARCIRCLE is the key to ARCIRCLE PAD. Every use below sends $ARCIRCLE to 0x…dEaD for good, and holding it opens the rest.": "$ARCIRCLE 是 ARCIRCLE PAD 的钥匙。下面每一种用途都会把 $ARCIRCLE 永久送到 0x…dEaD,持有它还能解锁其余功能。",
    "Hold": "持有",
    "Vote on CirclePad": "CirclePad 投票",
    "Burn-to-vote decides each round's name, ticker, logo and roadmap. One vote burns 1,000 $ARCIRCLE.": "销毁投票决定每轮的名称、代码、Logo 与路线图。每票销毁 1,000 $ARCIRCLE。",
    "Unlock Token Scanner tools": "解锁代币扫描器工具",
    "Plus and Pro tools past the free daily unlocks: 1,000 or 2,000 $ARCIRCLE burned per unlock.": "超过每日免费次数后的 Plus 与 Pro 工具:每次解锁销毁 1,000 或 2,000 $ARCIRCLE。",
    "Mine on Builder Mine": "在 Builder Mine 挖矿",
    "Joining a mine burns 1 USDC worth of $ARCIRCLE; pickaxes and boosts are paid in $ARCIRCLE and burned. Holding 100K / 1M / 5M adds +10 / 20 / 30% to your payouts.": "加入矿场会销毁价值 1 USDC 的 $ARCIRCLE;镐和加成以 $ARCIRCLE 支付并销毁。持有 100K / 1M / 5M 可让收益 +10 / 20 / 30%。",
    "Receive Relay launches": "接收接力发币",
    "Each CirclePad round's first buy is relayed to its contributors and to every wallet holding 100,000+ $ARCIRCLE at the snapshot.": "每轮 CirclePad 的首笔买入会接力给贡献者,以及快照时持有 100,000+ $ARCIRCLE 的每个钱包。",
    "Open ARCIA's secret file": "打开 ARCIA 的秘密档案",
    "ARCIA's private photo file opens once per wallet for 100,000 $ARCIRCLE, burned.": "ARCIA 的私人照片档案每个钱包开启一次,需销毁 100,000 $ARCIRCLE。",
    "Utility and platform revenue into a reward contract that buys back and burns $ARCIRCLE and $ARCIA automatically.": "工具与平台收入进入奖励合约,自动回购并销毁 $ARCIRCLE 与 $ARCIA。",
