    "A stronger $ARCIRCLE funds holder and creator rewards (planned) and draws in more creators — so the next round of launches is bigger.": "更强的 $ARCIRCLE 支撑持有者与创作者奖励(计划中),吸引更多创作者 — 下一轮发币会更大。",
