    "Per buy, per day (not below one buy) and at least 1 minute between buys.": "请填写每笔、每天（不低于每笔）以及至少 1 分钟的买入间隔。",
    "Pick a pool and set the limits (at least 1 minute between buys).": "选择一个池并设置限额（买入间隔至少 1 分钟）。",
    "Reading its pools and liquidity": "正在读取池和流动性",
    "Record": "记录",
    "Risky": "高风险",
    "Risky calls right": "高风险判断命中",
    "Running Token Scanner v3": "正在运行代币扫描器 v3",
    "Safe": "安全",
    "Safe calls right": "安全判断命中",
    "Safe is right if the token didn't go bad in 24 hours; Risky is right if it did. \"Bad\" = the price fell 60% or more, or the liquidity 50% or more. Each call's hash is recorded before the outcome.": "安全判断在 24 小时内没有变坏即为命中；高风险判断在变坏时命中。“变坏”= 价格下跌 60% 以上，或流动性减少 50% 以上。每个判断的哈希在结果出来之前就已记录。",
    "Set limits": "设置限额",
    "The call's hash, recorded before the outcome": "在结果之前记录的判断哈希",
    "The record isn't reachable right now.": "暂时无法读取记录。",
    "They open once the ARCIA AGENT contracts are deployed on Arc — the date isn't decided yet. Everything else here works now.": "ARCIA AGENT 合约部署到 Arc 后开放——日期尚未确定。这里的其他功能现在就能用。",
    "This token": "这个代币",
    "This wallet doesn't hold that much USDC.": "这个钱包没有那么多 USDC。",
    "Tighter limits apply at once; looser ones wait an hour.": "收紧的限额立即生效；放宽的需等待一小时。",
    "Turn ARCIA off": "关闭 ARCIA",
    "Turn ARCIA on": "开启 ARCIA",
    "USDC ready": "可用 USDC",
    "Vault": "金库",
    "Vault open. Fund it and ARCIA starts watching.": "金库已开设。充值后 ARCIA 就开始观察。",
    "Wake ARCIA": "唤醒 ARCIA",
    "Weighing the risks": "正在权衡风险",
    "What ARCIA would watch": "ARCIA 会关注的地方",
    "one buy every": "买入间隔",
    "every (minutes)": "间隔（分钟）",
    "every safety call, graded in public": "每个安全判断，公开评分",
    "no market to grade": "无市场可评分",
    "not graded": "不评分",
    "per buy / per day": "每笔 / 每天",
    "read by ARCIA": "ARCIA 读取于",
    "called right": "判断正确",
    "called wrong": "判断错误",
    "still open": "进行中",
    "Paste an Arc token — ARCIA reads it, calls it, and burns it from its vault": "粘贴一个 Arc 代币——ARCIA 读取、判断，并用金库销毁它",
    "A call is about risk, never about price direction. It's not a signal to buy or sell anything.": "判断针对风险，而不是价格方向。它不是任何买卖信号。",
    "ARCIA AGENT guide": "ARCIA AGENT 指南",
    "ARCIA decides when to spend it, and the only thing she can do is buy that token and send it to 0x…dEaD. There is no function that sells, and nothing bought stays in the vault.": "何时使用由 ARCIA 决定，她唯一能做的就是买入该代币并发送到 0x…dEaD。没有任何卖出功能，买到的东西不会留在金库里。",
    "ARCIA's agent for any token on Arc. Paste a token's contract address and she reads it end to end with Token Scanner v3 (contract, holders, liquidity, market), tells you in plain words what stands out, and makes a safety call. Tokens with a burn vault get her as their buyer: she decides when to buy and burns everything she buys.": "ARCIA 为 Arc 上任何代币提供的代理。粘贴代币合约地址，她会用代币扫描器 v3 完整读取（合约、持有者、流动性、市场），用简单的话说明值得注意的地方，并给出安全判断。有销毁金库的代币由她负责买入：她决定何时买入，并销毁买到的全部代币。",
    "Anyone can open a vault for an Arc token that trades against USDC on Uniswap v4 (Argus, ArcPad or a plain pool). Anyone can fund it with USDC.": "任何在 Uniswap v4 上与 USDC 交易的 Arc 代币（Argus、ArcPad 或普通池），任何人都可以开设金库，也都可以用 USDC 充值。",
    "Burn vaults": "销毁金库",
    "Burning a token doesn't make its price go up, and ARCIA's calls can be wrong. Vault contracts are new and unaudited: fund only what you can afford to lose. Nothing here is financial advice, and no message, chat or command can make ARCIA buy — only the vault's rules can.": "销毁代币不会让价格上涨，ARCIA 的判断也可能出错。金库合约是新的且未经审计：只放你能承受损失的金额。这里的内容都不是投资建议，任何消息、聊天或指令都不能让 ARCIA 买入——只有金库的规则可以。",
    "Every report comes with a call for the next 24 hours: Safe, Caution or Risky. The call is recorded with a hash before the outcome exists, then graded from the market: it \"went bad\" if the price fell 60% or more, or the liquidity 50% or more. A Safe call is right if it didn't go bad; a Risky call is right if it did. Caution isn't graded. One call per token every 12 hours. The Record tab shows every call and the hit rate.": "每份报告都附带未来 24 小时的判断：安全、谨慎或高风险。判断在结果出现之前连同哈希一起记录，之后按市场评分：价格下跌 60% 以上或流动性减少 50% 以上即为“变坏”。安全判断在没有变坏时命中；高风险判断在变坏时命中。谨慎不评分。每个代币每 12 小时判断一次。记录标签页显示所有判断和命中率。",
    "Paste an Arc token's address and ARCIA goes to work on it: she reads the whole token, makes a safety call for the next 24 hours that's graded in public, and — from a vault anyone can fund — buys it back and burns it, in dips, never chasing a pump.": "粘贴一个 Arc 代币地址，ARCIA 就开始工作：读取整个代币，给出公开评分的 24 小时安全判断，并用任何人都能充值的金库回购并销毁它——只在回调时买，从不追涨。",
    "Reads · calls · burns": "读取 · 判断 · 销毁",
    "Safety calls, graded in public": "公开评分的安全判断",
    "She buys in dips: she watches the price first, never buys after a +8% move in 15 minutes or +20% in an hour, sizes each buy so it moves the price at most 3%, and stops if a buy-and-sell round trip would lose more than 30% (a hostile tax).": "她只在回调时买：先观察价格，15 分钟内上涨 8% 或 1 小时内上涨 20% 后不买，每笔大小控制在最多推动价格 3%，如果买入再卖出会损失超过 30%（恶意税）就停止。",
    "The owner can pause the vault, turn ARCIA off, and withdraw the USDC at any time — always to the owner's own wallet. The team can stop every vault at once but can't touch anyone's money, and a new ARCIA key only takes effect 24 hours after it's announced.": "所有者可以随时暂停金库、关闭 ARCIA 并提取 USDC——总是转到所有者自己的钱包。团队可以一次停止所有金库，但不能动任何人的钱；新的 ARCIA 密钥在公布 24 小时后才生效。",
    "The vault's owner sets the limits: most per buy, most per UTC day, and time between buys (at least a minute). Tighter limits apply at once; looser ones wait an hour.": "限额由金库所有者设置：每笔最多、每个 UTC 日最多，以及买入间隔（至少一分钟）。收紧的限额立即生效；放宽的需等待一小时。",
    "Utility · ARCIA works on any Arc token": "工具 · ARCIA 为任何 Arc 代币工作",
    "What is ARCIA AGENT?": "什么是 ARCIA AGENT？",
