    "Once a day, ARCIA writes the day's call hashes on Arc as one root, so anyone can check the calls came before their outcomes. The first one is written the day after the first calls.": "ARCIA 每天一次把当天判断的哈希合成一个根写到 Arc 上，任何人都能核对判断先于结果。第一次记录在首批判断的次日写入。",
