    "couldn't check right now": "暂时无法核对",
    "doesn't match": "不一致",
    "each buy ≤ 2% of hourly volume": "每笔 ≤ 每小时成交量的 2%",
    "holders not read yet": "持有者尚未读取",
    "matches": "一致",
    "never after a pump": "急涨后不买",
    "new safety call": "新的安全判断",
    "one buy each interval": "每个间隔买一次",
    "reading the holders first": "先读取持有者",
    "safety call": "安全判断",
    "steady buy": "稳定买入",
    "still reading the holders": "仍在读取持有者",
    "volume-sized buy": "按成交量买入",
    "waiting for the token's trading volume": "等待代币成交量数据",
    "Each vault has a strategy its owner signs (no gas): Dips only (the default), Steady (one buy each interval, whatever the price did) or By volume (each buy at most 2% of the token's hourly trading volume).": "每个金库都有所有者签名设定的策略（无 gas）：只在回调时（默认）、稳定（不论价格，每个间隔买一次）或按成交量（每笔最多为代币每小时成交量的 2%）。",
    "Once a day, ARCIA writes the previous day's call hashes on Arc as one root, from her own wallet. The Record tab re-computes that root in your browser and compares it with the transaction, so anyone can check the calls were made before their outcomes.": "ARCIA 每天一次用自己的钱包把前一天判断的哈希合成一个根写到 Arc 上。记录标签页会在你的浏览器中重新计算这个根并与交易比对，任何人都能核对判断先于结果。",
    "The server's ARCIA_AGENT_KEY isn't a valid private key (64 hex characters, no quotes or spaces).": "服务器上的 ARCIA_AGENT_KEY 不是有效的私钥（64 个十六进制字符，不含引号或空格）。",
    "The server's key belongs to": "服务器上的密钥属于",
    "not ARCIA's operator": "而不是 ARCIA 的 operator",
    "Which desk": "哪个交易台",
    "USDC · Argus launches": "USDC · Argus 新币",
    "ETH · pons launches": "ETH · pons 新币",
    "new pons launches": "新的 pons 新币",
    "In ETH": "以 ETH 计",
    "ETH at": "ETH 价格",
    "Profit in ETH": "以 ETH 计的盈亏",
    "ETH's own price moves left out": "不计 ETH 自身的价格波动",
    "WETH in the desk contract": "交易台合约中的 WETH",
    "Open on Robinhood Chain's explorer": "在 Robinhood Chain 浏览器中打开",
    "No pons launches in the last three days yet.": "最近三天还没有 pons 新币。",
    "Holders read from every transfer since launch (young tokens)": "从上线以来的每笔转账读取持有人（新代币）",
    "pons tokens are the factory's own fixed-supply tokens — no taxes, no owner switches, nothing that can block selling; what's left is who holds them": "pons 代币是工厂发行的固定供应代币——没有税、没有所有者开关、没有能阻止卖出的机制；剩下的风险是谁持有它们",
    "Only new coins launched on pons (Robinhood Chain), in their Uniswap v3 pools paired with WETH": "只交易在 pons（Robinhood Chain）上线的新币，在其与 WETH 配对的 Uniswap v3 池中",
    "The money is held as ETH (WETH): returns and the day's result are counted in ETH, so ETH's own price moves aren't wins or losses; dollars are shown at the current ETH price": "资金以 ETH（WETH）持有：收益和当日结果以 ETH 计算，因此 ETH 自身的价格波动不算盈亏；美元金额按当前 ETH 价格显示",
    "No burn on this chain": "此链上没有销毁",
    "WETH in the contract": "合约中的 WETH",
    "Send ETH on Robinhood Chain from your wallet to the desk contract — it becomes WETH there.": "从你的钱包在 Robinhood Chain 上把 ETH 发送到交易台合约——在那里会变成 WETH。",
    "Withdraw, pause, limits": "提取、暂停、限额",
    "In the contract's Write tab on the explorer, from the owner wallet: withdrawETH (always to the owner), setPaused, setCaps (in wei).": "在浏览器合约的 Write 标签页中，用所有者钱包操作：withdrawETH（总是转给所有者）、setPaused、setCaps（以 wei 为单位）。",
    "Open the contract": "打开合约",
    "Utility · ARCIA trades on Arc and Robinhood Chain": "工具 · ARCIA 在 Arc 和 Robinhood Chain 上交易",
    "ARCIA trades new coins — Argus launches on Arc, new launches on Robinhood Chain — with her own small wallets and learns from every trade. Every buy and sell is an on-chain transaction, shown here the moment it happens — and on Arc, part of each day's new profit buys and burns $ARCIRCLE.": "ARCIA 用自己的小钱包交易新币——Arc 上的 Argus 新币和 Robinhood Chain 上的新发行币——并从每笔交易中学习。每一笔买卖都是链上交易，发生时即在此显示；在 Arc 上，每天新增利润的一部分会买入并销毁 $ARCIRCLE。",
    "today's limit is used up — buying again after 00:00 UTC": "今天的额度已用完——00:00 UTC 后再买入",
    "the per-buy limit is under the $0.50 minimum": "单次限额低于最低 $0.50",
    "Paste an Arc token: she reads it, makes a 24-hour safety call and burns it from vaults anyone can fund": "粘贴一个 Arc 代币：她读取它、给出 24 小时安全判断，并用任何人都能充值的金库回购销毁",
