    "position is open — its coins aren't ETH yet. Pause first and wait for it to close to take everything out.": "个仓位未平——它的代币还不是 ETH。要全部取出，请先暂停并等它平仓。",
    "positions are open — their coins aren't ETH yet. Pause first and wait for them to close to take everything out.": "个仓位未平——它们的代币还不是 ETH。要全部取出，请先暂停并等它们平仓。",
    "ETH · new launches": "ETH · 新发行",
    "new Robinhood Chain launches": "Robinhood Chain 新发行",
    "No new launches in the last three days yet.": "最近三天还没有新发行。",
    "Before every buy the desk buys and sells straight back in a dry run: a token that taxes or can't be sold back shows there and isn't bought": "每次买入前，交易台都会模拟买入后立即卖回：收税或无法卖回的代币会在这里暴露，不会被买入",
    "Any new coin launched on Robinhood Chain — the new pairs Dexscreener lists there (pools.trade, Bags, pons and others): Uniswap v4 pools paired with ETH and v3 pools paired with WETH": "Robinhood Chain 上任何新发行的币 —— Dexscreener 上列出的新交易对（pools.trade、Bags、pons 等）：与 ETH 配对的 Uniswap v4 池和与 WETH 配对的 v3 池",
    "0–{n}%. An extra fee on every trade, on top of Pons's own, paid to the coin's fee recipient — 70% you, 30% ARCIRCLE PAD. Fixed at launch.": "0–{n}%。每笔交易在 Pons 自身费用之外额外收取，付给代币的费用接收地址——70% 归你，30% 归 ARCIRCLE PAD。发射时固定。",
    "A field is too long for Pons — shorten the description or a link.": "有字段超出 Pons 的长度限制——请缩短描述或链接。",
    "A link is too long for Pons.": "链接超出 Pons 的长度限制。",
    "A payout wallet refused the ETH.": "收款钱包拒收 ETH。",
    "An extra fee on every trade, on top of Pons's own, paid to the coin's fee recipient — 70% you, 30% ARCIRCLE PAD. Fixed at launch.": "每笔交易在 Pons 自身费用之外额外收取，付给代币的费用接收地址——70% 归你，30% 归 ARCIRCLE PAD。发射时固定。",
    "ArcPad's fee splitter doesn't match this page — stopped before launching.": "ArcPad 费用分配合约与本页面不一致——已在发射前停止。",
    "ArcPad's fee splitter for Pons is being deployed — the Pons option opens as soon as it's live.": "Pons 的 ArcPad 费用分配合约正在部署——上线后 Pons 选项即开放。",
    "ArcPad's fee splitter for Pons is being deployed. The Pons option opens here as soon as it's live.": "Pons 的 ArcPad 费用分配合约正在部署。上线后即在此开放 Pons 选项。",
    "ArcPad's fee splitter isn't on Robinhood Chain — stopped before launching.": "ArcPad 费用分配合约不在 Robinhood Chain 上——已在发射前停止。",
    "Being set up": "准备中",
    "Buyback & lock — part of the creator fees buys the coin back and locks it (Pons's buyback). Off by default; you can switch it later from the coin's fee splitter.": "回购并锁定——用部分创作者费用回购代币并锁定（Pons 回购）。默认关闭；之后可通过代币的费用分配合约切换。",
    "Claim my 70%": "领取我的 70%",
