    "Creator fees": "创作者费用",
    "Every coin launched through ArcPad — on the ArcPad factory, on Argus, or on Pons on Robinhood Chain — read live from the chain.": "通过 ArcPad 发射的每个代币——ArcPad 工厂、Argus，或 Robinhood Chain 上的 Pons——均从链上实时读取。",
    "Fee recipient: your ArcPad splitter {a} · 70% you, 30% ARCIRCLE PAD": "费用接收：你的 ArcPad 分配合约 {a} · 70% 归你，30% 归 ARCIRCLE PAD",
    "Fees wait in Pons's fee escrow until claimed. Claim from the coin's card in Explore: one transaction pays both sides.": "费用在领取前存放在 Pons 的费用托管中。在探索页的代币卡片中领取：一笔交易同时支付双方。",
    "Graduated · Uniswap v4": "已毕业 · Uniswap v4",
    "I understand: one signature on Robinhood Chain plus Pons's launch fee in ETH, the 70 / 30 creator-fee split is permanent, and Pons V2 is unaudited.": "我已了解：在 Robinhood Chain 上签名一次并支付 Pons 的 ETH 发射费，70 / 30 创作者费用分配为永久，且 Pons V2 未经审计。",
    "In Explore under Pons": "已列入探索页的 Pons",
    "It trades on its Pons bonding curve until it graduates into a locked Uniswap v4 pool. Your 70% of the creator fees is claimed from the coin's card in Explore.": "在毕业进入锁定的 Uniswap v4 池之前，它在 Pons 联合曲线上交易。你的 70% 创作者费用可在探索页的代币卡片中领取。",
    "Launch on Pons": "在 Pons 发射",
