    "Launched on Pons, on Robinhood Chain, from your own wallet": "从你自己的钱包，在 Robinhood Chain 的 Pons 上发射",
    "Not enough ETH on Robinhood Chain for the launch fee and gas.": "Robinhood Chain 上的 ETH 不足以支付发射费和 Gas。",
    "Not enough ETH on Robinhood Chain — the launch needs {n} ETH plus gas; this wallet has {b} ETH there.": "Robinhood Chain 上的 ETH 不足——发射需要 {n} ETH 加 Gas；该钱包在那里有 {b} ETH。",
    "Of every 1 ETH of creator fees": "每 1 ETH 创作者费用中",
    "Paid out: 70% to you, 30% to ARCIRCLE PAD.": "已支付：70% 给你，30% 给 ARCIRCLE PAD。",
    "Paid to this coin's ArcPad splitter: 70% the creator, 30% ARCIRCLE PAD — set at launch, for good.": "付给该代币的 ArcPad 分配合约：70% 归创作者，30% 归 ARCIRCLE PAD——发射时永久设定。",
    "Pons changed its launch terms a moment ago — try again.": "Pons 刚刚更改了发射条件——请重试。",
    "Pons curve fee": "Pons 曲线费用",
    "Pons has no open launch setup right now.": "Pons 目前没有开放的发射配置。",
    "Pons needs a hosted logo link — upload the file (it's hosted for you) or paste an https:// image URL.": "Pons 需要托管的 Logo 链接——请上传文件（会自动托管）或粘贴 https:// 图片链接。",
    "Pons only lets whitelisted wallets launch right now — this wallet isn't on its list.": "Pons 目前仅允许白名单钱包发射——该钱包不在名单中。",
    "Pons only lets whitelisted wallets launch right now.": "Pons 目前仅允许白名单钱包发射。",
    "Pons rejected the name, symbol or links.": "Pons 拒绝了名称、代码或链接。",
