    "Reading Pons…": "正在读取 Pons…",
    "Robinhood Chain · bonding curve → Uniswap v4 · 70% of creator fees to you": "Robinhood Chain · 联合曲线 → Uniswap v4 · 70% 创作者费用归你",
    "Support may be refused if our Token Scanner finds signs of manipulation — snipers, bundled buys, wash trading or similar.": "如果我们的代币扫描器发现操纵迹象——狙击、捆绑买入、对敲交易等——可能拒绝支持。",
    "Support may be refused if our Token Scanner finds signs of manipulation. It is ARCIRCLE PAD's own policy, not a contract. Pons V2 is unaudited — trade with care.": "如果我们的代币扫描器发现操纵迹象，可能拒绝支持。这是 ARCIRCLE PAD 自己的政策，而非合约。Pons V2 未经审计——请谨慎交易。",
    "Switch to Robinhood Chain": "切换到 Robinhood Chain",
    "That logo link is too long for Pons — upload the file instead.": "Logo 链接超出 Pons 的长度限制——请改为上传文件。",
    "The creator tax is above Pons's cap.": "创作者税超过 Pons 的上限。",
    "The creator tax plus Pons's fee is above Pons's cap — lower the tax.": "创作者税加 Pons 费用超过 Pons 的上限——请降低税率。",
    "The description is too long for Pons.": "描述超出 Pons 的长度限制。",
    "The launch fee wasn't paid — try again.": "发射费未支付——请重试。",
    "The launch hasn't confirmed yet — check the transaction on Blockscout.": "发射尚未确认——请在 Blockscout 上查看交易。",
    "The launch transaction failed on Robinhood Chain.": "发射交易在 Robinhood Chain 上失败。",
    "The name or symbol is too long for Pons.": "名称或代码超出 Pons 的长度限制。",
    "This Pons launch setup was switched off — try again.": "该 Pons 发射配置已关闭——请重试。",
    "This is ARCIRCLE PAD's own support policy, not a contract, and it can change. The coin's fees follow Pons's rules. Pons V2 is new and unaudited.": "这是 ARCIRCLE PAD 自己的支持政策，而非合约，可能会调整。代币费用遵循 Pons 的规则。Pons V2 是新推出且未经审计的。",
    "Trade on Pons": "在 Pons 交易",
    "Wallet on Robinhood Chain: {b} ETH · the launch needs {n} ETH plus gas": "Robinhood Chain 钱包：{b} ETH · 发射需要 {n} ETH 加 Gas",
    "Your coin goes live on Pons V2: it trades on a bonding curve in ETH and, once the curve fills, graduates into a locked Uniswap v4 pool. Pons takes its own fees as usual. Every creator fee and creator tax goes to your ArcPad fee splitter — 70% to you, 30% to the ARCIRCLE PAD treasury — set in the launch itself, one signature.": "你的代币在 Pons V2 上线：先在 ETH 联合曲线上交易，曲线填满后毕业进入锁定的 Uniswap v4 池。Pons 照常收取自身费用。所有创作者费用和创作者税都进入你的 ArcPad 费用分配合约——70% 给你，30% 给 ARCIRCLE PAD 金库——在发射交易中设定，只需一次签名。",
